+---
+# This file is generated by `scripts/compile-workflow-sources/main.go` from `.github/workflows-src/flaky-test-catcher/workflow.md.tmpl`. Do not edit directly.
+name: Flaky Test Catcher
+description: Detects broken and flaky acceptance tests on main and opens GitHub issues for automated remediation.
+on:
+  workflow_dispatch:
+  schedule:
+    - cron: daily
+  steps:
+    - name: Check CI failures
+      id: check_ci_failures
+      uses: actions/github-script@v9
+      with:
+        github-token: ${{ secrets.GITHUB_TOKEN }}
+        script: |
+          /**
+           * Computes issue slot availability for a labeled issue bucket.
+           * @param {{ label: string, issueCap: number | string, openIssueCount: number }} params
+           * @returns {{ open_issues: number, issue_slots_available: number, gate_reason: string }}
+           */
+          function computeIssueSlots({ label, issueCap, openIssueCount }) {
+            const normalizedLabel = String(label).trim();
+            const cap = Number(issueCap);
+          
+            if (!normalizedLabel) {
+              throw new Error('issue slot label must be a non-empty string');
+            }
+          
+            if (!Number.isInteger(cap) || cap < 0) {
+              throw new Error(`issue cap must be a non-negative integer, got: ${issueCap}`);
+            }
+          
+            if (!Number.isInteger(openIssueCount) || openIssueCount < 0) {
+              throw new Error(`open issue count must be a non-negative integer, got: ${openIssueCount}`);
+            }
+          
+            const slotsAvailable = Math.max(0, cap - openIssueCount);
+          
+            let gateReason;
+            if (slotsAvailable === 0) {
+              gateReason = `Issue cap reached: ${openIssueCount} open ${normalizedLabel} issue(s), cap is ${cap}. Agent job will be skipped.`;
+            } else {
+              gateReason = `${slotsAvailable} slot(s) available: ${openIssueCount} open ${normalizedLabel} issue(s), cap is ${cap}.`;
+            }
+          
+            return {
+              open_issues: openIssueCount,
+              issue_slots_available: slotsAvailable,
+              gate_reason: gateReason,
+            };
+          }
+          
+          if (typeof module !== 'undefined') {
+            module.exports = { computeIssueSlots };
+          }
+          
+          /**
+           * Pure helper functions for the flaky-test-catcher workflow.
+           * These are extracted from check_ci_failures.inline.js so they can be unit-tested.
+           */
+          
+          /**
+           * Conclusions that represent meaningful completed runs for the purpose of
+           * computing fail rates. Cancelled and skipped runs are excluded because they
+           * don't reflect a real test outcome and would dilute the denominator.
+           */
+          const COUNTABLE_CONCLUSIONS = new Set(['success', 'failure', 'timed_out', 'neutral', 'action_required']);
+          
+          /**
+           * Classifies an array of workflow run objects into failed runs and total count.
+           *
+           * Only runs with countable conclusions (success, failure, timed_out, neutral,
+           * action_required) are included in `totalRunCount`. Cancelled and skipped runs
+           * are omitted from the total to avoid understating fail rates.
+           *
+           * Runs are pre-filtered by date via the GitHub API `created` parameter, so
+           * this function does not re-filter by date.
+           *
+           * @param {Array<{ id: number, conclusion: string | null }>} runs - Workflow run objects
+           * @returns {{ failedRunIds: number[], totalRunCount: number }}
+           */
+          function classifyRuns(runs) {
+            const failedRunIds = [];
+            let totalRunCount = 0;
+            for (const run of runs) {
+              if (COUNTABLE_CONCLUSIONS.has(run.conclusion)) {
+                totalRunCount++;
+              }
+              if (run.conclusion === 'failure') {
+                failedRunIds.push(run.id);
+              }
+            }
+            return { failedRunIds, totalRunCount };
+          }
+          
+          /**
+           * Filters a list of GitHub issues/PR items, returning only real issues.
+           * The GitHub issues API may return pull requests; this removes them.
+           *
+           * @param {Array<{ pull_request?: object }>} items - Items from listForRepo
+           * @returns {Array<{ pull_request?: object }>}
+           */
+          function filterIssues(items) {
+            return items.filter(item => !item.pull_request);
+          }
+          
+          /**
+           * Computes the gate decision for the flaky-test-catcher workflow.
+           *
+           * @param {number[]} failedRunIds - IDs of failed workflow runs
+           * @param {{ open_issues: number, issue_slots_available: number, gate_reason: string }} issueSlots - Output from computeIssueSlots
+           * @returns {{ has_ci_failures: string, gate_reason: string }}
+           */
+          function computeGate(failedRunIds, issueSlots) {
+            const hasCiFailures = failedRunIds.length > 0;
+          
+            if (!hasCiFailures) {
+              return {
+                has_ci_failures: 'false',
+                gate_reason: `No CI failures detected on main in the last 3 days. Agent job will be skipped.`,
+              };
+            }
+          
+            if (issueSlots.issue_slots_available === 0) {
+              return {
+                has_ci_failures: 'true',
+                gate_reason: `CI failures detected (${failedRunIds.length} failed run(s)), but ${issueSlots.gate_reason}`,
+              };
+            }
+          
+            return {
+              has_ci_failures: 'true',
+              gate_reason: `CI failures detected: ${failedRunIds.length} failed run(s) on main. ${issueSlots.gate_reason}`,
+            };
+          }
+          
+          if (typeof module !== 'undefined') {
+            module.exports = { classifyRuns, computeGate, filterIssues };
+          }
+          
+          const ISSUE_LABEL = 'flaky-test';
+          const ISSUE_CAP = 3;
+          
+          const { owner, repo } = context.repo;
+          
+          // Calculate the cutoff date for the 3-day window
+          const cutoffDate = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000);
+          
+          // Query workflow runs for test.yml on main in the last 3 days.
+          // The `created` filter uses a date (not datetime) prefix so we may get some
+          // runs from just before the cutoff hour; that is acceptable.
+          const allRuns = await github.paginate(github.rest.actions.listWorkflowRuns, {
+            owner,
+            repo,
+            workflow_id: 'test.yml',
+            branch: 'main',
+            status: 'completed',
+            created: `>=${cutoffDate.toISOString().split('T')[0]}`,
+            per_page: 100,
+          });
+          
+          const { failedRunIds, totalRunCount } = classifyRuns(allRuns);
+          
+          // Count open GitHub issues labelled `flaky-test`, excluding pull requests
+          const issues = await github.paginate(github.rest.issues.listForRepo, {
+            owner,
+            repo,
+            labels: ISSUE_LABEL,
+            state: 'open',
+            per_page: 100,
+          });
+          
+          const openIssueCount = filterIssues(issues).length;
+          
+          const issueSlots = computeIssueSlots({
+            label: ISSUE_LABEL,
+            issueCap: ISSUE_CAP,
+            openIssueCount,
+          });
+          
+          const gate = computeGate(failedRunIds, issueSlots);
+          
+          core.setOutput('has_ci_failures', gate.has_ci_failures);
+          core.setOutput('failed_run_ids', JSON.stringify(failedRunIds));
+          core.setOutput('total_run_count', String(totalRunCount));
+          core.setOutput('open_issues', String(issueSlots.open_issues));
+          core.setOutput('issue_slots_available', String(issueSlots.issue_slots_available));
+          core.setOutput('gate_reason', gate.gate_reason);
+          
+          core.info(`Gate reason: ${gate.gate_reason}`);
+          core.info(`Failed run IDs: ${JSON.stringify(failedRunIds)}`);
+          core.info(`Total runs in window: ${totalRunCount}`);
+          
+engine:
+  id: claude
+  model: "llm-gateway/claude-sonnet-4-6"
+  args:
+    - "--effort"
+    - "high"
+  env:
+    ANTHROPIC_BASE_URL: "https://elastic.litellm-prod.ai/"
+    ANTHROPIC_API_KEY: ${{ secrets.CLAUDE_LITELLM_PROXY_API_KEY }}
+permissions:
+  contents: read
+  issues: read
+  actions: read
+safe-outputs:
+  create-issue:
+    title-prefix: "[flaky-test] "
+    labels: [flaky-test, code-factory]
+    max: 3
+  noop:
+    max: 1
+    report-as-issue: false
+checkout:
+  fetch-depth: 0
+network:
+  allowed: [defaults, elastic.litellm-prod.ai]
+if: >-
+  needs.pre_activation.outputs.has_ci_failures == 'true' &&
+  needs.pre_activation.outputs.issue_slots_available != '0'
+jobs:
+  pre-activation:
+    outputs:
+      has_ci_failures: ${{ steps.check_ci_failures.outputs.has_ci_failures }}
+      failed_run_ids: ${{ steps.check_ci_failures.outputs.failed_run_ids }}
+      total_run_count: ${{ steps.check_ci_failures.outputs.total_run_count }}
+      open_issues: ${{ steps.check_ci_failures.outputs.open_issues }}
+      issue_slots_available: ${{ steps.check_ci_failures.outputs.issue_slots_available }}
+      gate_reason: ${{ steps.check_ci_failures.outputs.gate_reason }}
+---
+
+# Flaky Test Catcher Worker
+
+You are responsible for detecting broken and flaky acceptance tests on `main` and opening GitHub issues to trigger automated remediation.
+
+## Pre-activation context
+
+A deterministic pre-activation step has already queried CI run history and computed issue capacity for this run. Do **not** query GitHub issue counts or CI failure counts yourself; use only the values below.
+
+- **has_ci_failures**: `${{ needs.pre_activation.outputs.has_ci_failures }}`
+- **failed_run_ids** (JSON array): `${{ needs.pre_activation.outputs.failed_run_ids }}`
+- **total_run_count**: `${{ needs.pre_activation.outputs.total_run_count }}`
+- **Open flaky-test issues**: `${{ needs.pre_activation.outputs.open_issues }}`
+- **Issue slots available**: `${{ needs.pre_activation.outputs.issue_slots_available }}`
+- **Gate reason**: ${{ needs.pre_activation.outputs.gate_reason }}
+
+The workflow reached this point only because `has_ci_failures` is `true` and `issue_slots_available` is non-zero. You may open up to `${{ needs.pre_activation.outputs.issue_slots_available }}` new issues in this run.
+
+## Required inputs and references
+
+- Skill instructions: `.agents/skills/flaky-test-catcher/SKILL.md`
+
+## Execution steps
+
+1. Read `.agents/skills/flaky-test-catcher/SKILL.md` and follow it strictly when performing analysis.
+2. Parse `failed_run_ids` from pre-activation — it is a JSON array of numbers (e.g. `[12345, 67890]`). These are the run IDs of failed `test.yml` workflow runs on `main` in the last 3 days.
+3. For each failed run ID, fetch job logs using `gh api` and extract all `--- FAIL:` test names from the output. Collect every failing test name across all runs.
+4. Apply fail-rate classification using `total_run_count` from pre-activation:
+   - **Broken**: test fails in 100% of runs (always-failing).
+   - **Flaky**: test fails in ≥ 20% but < 100% of runs.
+   - Tests failing in < 20% of runs are noise — ignore them.
+5. Group failing tests by their base test name, extracted via the pattern `TestAcc[^_]+` (the part before the first `_` suffix). For example, `TestAccResourceFoo_basic` and `TestAccResourceFoo_update` both belong to base test `TestAccResourceFoo`.
+6. For each affected base test name, check for an existing open issue with the `flaky-test` label and title `[flaky-test] <BaseTestName>`. Skip base tests that already have an open issue (deduplication).
+7. For each new issue to create (up to `${{ needs.pre_activation.outputs.issue_slots_available }}`):
+   a. Perform commit analysis: inspect commits on `main` since the oldest failing run that touch files in the affected resource package (by path or referencing the test/resource name). For each such commit, note its SHA, message, and changed files. If any commit appears to address the failure (e.g. a fix or revert), note: "may already be addressed in `<sha>`". Frame this as "has someone already fixed this?" — not as attribution of blame.
+   b. Collect a sample failure log excerpt (the most informative `--- FAIL:` block from the logs).
+   c. Note the Elastic Stack versions reported in the failing job logs, if present.
+   d. Create the issue using the `create-issue` safe output.
+8. If no issues were created after completing analysis (all deduped, all below threshold, or no `--- FAIL:` patterns found), call `noop` with a descriptive reason.
+
+## Issue creation rules
+
+- Never create more than `${{ needs.pre_activation.outputs.issue_slots_available }}` issues in a single run.
+- Label each issue `flaky-test` and `code-factory`.
+- Issue title format: `<BaseTestName>` (the `[flaky-test] ` prefix is added automatically by `create-issue`).
+
+Each issue body must include the following sections (use `##` headings to match SKILL.md):
+
+## Broken Tests
+List the specific test function names (with subtests) that failed in 100% of sampled runs.
+
+## Flaky Tests
+List the specific test function names that failed in ≥ 20% but < 100% of runs, with each test's observed fail rate (e.g. `3/5 runs`).
+
+## Commit Analysis
+Note any commits on `main` since the oldest failing run that appear to address the failure. If a relevant fix commit is found, note: "may already be addressed in `<sha>`". If no relevant commits found, note that explicitly.
+
+## Sample Failure Output
+Paste the most informative `--- FAIL:` log excerpt from the failed runs to give context to the implementer.
+
+## Affected Stack Versions
+List the Elastic Stack versions (Elasticsearch, Kibana) reported in the failing job environment, if discoverable from the logs or job metadata.
+
+## Noop conditions
+
+Call `noop` with a concise explanation when:
+- All affected base tests already have an open `flaky-test` issue (nothing new to open).
+- All test failures are below the 20% fail-rate threshold (noise only, no actionable signal).
+- No `--- FAIL:` patterns were found in any of the failed run logs.

